import { readFileSync } from 'node:fs';

/** One static file of the web UI. */
export interface UiAsset {
  body: Buffer;
  type: string;
}

/** The dashboard. All of these must exist, or the dashboard is switched off. */
const DASHBOARD_FILES: Record<string, string> = {
  'index.html': 'text/html; charset=utf-8',
  'app.js': 'text/javascript; charset=utf-8',
  'qr.js': 'text/javascript; charset=utf-8',
  'util.js': 'text/javascript; charset=utf-8',
  'style.css': 'text/css; charset=utf-8',
};

/** The offline POS. `pos.js` is generated by `npm run build`, so these are only served when it is present. */
const POS_FILES: Record<string, string> = {
  'pos.html': 'text/html; charset=utf-8',
  'pos.js': 'text/javascript; charset=utf-8',
  'pos.css': 'text/css; charset=utf-8',
  'pos-sw.js': 'text/javascript; charset=utf-8',
  'manifest.webmanifest': 'application/manifest+json',
  'icon.svg': 'image/svg+xml',
};

/** URL path -> file. An allow-list, so no request path is ever turned into a filesystem path. */
const ROUTES: Record<string, string> = {
  '/': 'index.html',
  '/ui': 'index.html',
  '/ui/index.html': 'index.html',
  '/ui/app.js': 'app.js',
  '/ui/qr.js': 'qr.js',
  '/ui/util.js': 'util.js',
  '/ui/style.css': 'style.css',
  '/ui/pos.html': 'pos.html',
  '/ui/pos.js': 'pos.js',
  '/ui/pos.css': 'pos.css',
  '/ui/pos-sw.js': 'pos-sw.js',
  '/ui/manifest.webmanifest': 'manifest.webmanifest',
  '/ui/icon.svg': 'icon.svg',
};

/** Where the POS lives. It sits under /ui/ so its service worker's scope (/ui/) covers the page and its assets. */
export const POS_PATH = '/ui/pos.html';

/**
 * These pages hold an API key, so their headers are strict: only same-origin scripts, styles and workers (no inline
 * script, nothing third-party), no framing, no form posts, no referrer.
 */
export const UI_HEADERS: Record<string, string> = {
  'content-security-policy':
    "default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; manifest-src 'self'; worker-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'",
  'x-content-type-options': 'nosniff',
  'x-frame-options': 'DENY',
  'referrer-policy': 'no-referrer',
  'cache-control': 'no-cache',
};

export class DashboardAssets {
  private constructor(
    private readonly files: Map<string, UiAsset>,
    /** Whether the offline POS is available (its bundle was built). */
    readonly hasPos: boolean,
  ) {}

  /**
   * Reads the web UI files from `packages/server/ui`. That folder sits beside both `src/` and `dist/`, so the same
   * relative path works from source (tests) and from the build. Returns undefined, with a warning, if the dashboard
   * files are missing, so an API-only deployment that dropped them still starts.
   */
  static load(dir: URL = new URL('../ui/', import.meta.url)): DashboardAssets | undefined {
    const files = new Map<string, UiAsset>();
    try {
      for (const [name, type] of Object.entries(DASHBOARD_FILES)) files.set(name, { body: readFileSync(new URL(name, dir)), type });
    } catch (err) {
      console.warn(`[paycryt] dashboard files not found, the web UI is disabled (${err instanceof Error ? err.message : String(err)})`);
      return undefined;
    }
    let hasPos = true;
    try {
      for (const [name, type] of Object.entries(POS_FILES)) files.set(name, { body: readFileSync(new URL(name, dir)), type });
    } catch {
      hasPos = false;
      for (const name of Object.keys(POS_FILES)) files.delete(name);
      console.warn('[paycryt] the offline POS app is not built (ui/pos.js missing). Run `npm run build` to enable /ui/pos.html.');
    }
    return new DashboardAssets(files, hasPos);
  }

  /** The asset for a request path, or undefined if this path isn't part of the web UI. */
  lookup(path: string): UiAsset | undefined {
    const name = Object.prototype.hasOwnProperty.call(ROUTES, path) ? ROUTES[path] : undefined;
    return name ? this.files.get(name) : undefined;
  }
}
